// Loads and indexes all learning content (docs/CONTENT_SPEC.md).
// dist: one fetch of content/bundle.json (curriculum + vocab + verbs; topics lazily from content/topics/<id>.json). dev: curriculum.json + vocab/index.json (generated by tools/serve.mjs)
// + every listed shard + verbs.json; topic files are fetched lazily by getTopic().
import { LEVELS, levelIdx } from './german.js';

async function getJSON(fetchFn, url) {
  const res = await fetchFn(url);
  if (!res || !res.ok) throw new Error(`${url}: HTTP ${res ? res.status : '?'}`);
  return res.json();
}

/**
 * loadContent({base='content/', fetch, preferBundle=true}) → Content
 * Never throws for missing optional files; problems are collected in content.errors.
 */
export async function loadContent(opts = {}) {
  const base = opts.base ?? 'content/';
  const fetchFn = opts.fetch || ((u) => globalThis.fetch(u));
  const errors = [];
  let bundle = null;
  if (opts.preferBundle !== false) {
    try { bundle = await getJSON(fetchFn, base + 'bundle.json'); } catch { bundle = null; }
  }
  if (bundle) return new Content({ ...bundle, mode: 'bundle', base, fetchFn, errors });

  let curriculum = { levels: [], topics: [] };
  try { curriculum = await getJSON(fetchFn, base + 'curriculum.json'); } catch (e) { errors.push(String(e.message || e)); }

  let shards = [];
  try {
    const idx = await getJSON(fetchFn, base + 'vocab/index.json');
    shards = Array.isArray(idx) ? idx : idx.shards || [];
  } catch (e) { errors.push(`vocab index: ${e.message || e}`); }
  const vocab = (await Promise.all(shards.map(async (s) => {
    const file = s.endsWith('.json') ? s : `${s}.json`;
    try { return await getJSON(fetchFn, `${base}vocab/${file}`); } catch (e) { errors.push(String(e.message || e)); return null; }
  }))).filter(Boolean);

  let verbs = { verbs: [] };
  try { verbs = await getJSON(fetchFn, base + 'verbs.json'); } catch (e) { errors.push(String(e.message || e)); }

  return new Content({ curriculum, topics: {}, vocab, verbs, mode: 'files', base, fetchFn, errors });
}

/** Build a Content directly from objects (tests / node). */
export function contentFromData({ curriculum, topics = {}, vocab = [], verbs = { verbs: [] } }) {
  return new Content({ curriculum, topics, vocab, verbs, mode: 'data', errors: [] });
}

export class Content {
  constructor({ curriculum, topics, vocab, verbs, mode, base, fetchFn, errors, version }) {
    this.mode = mode;
    this.version = version || null;
    this.base = base;
    this._fetch = fetchFn;
    this.errors = errors || [];
    this.curriculum = curriculum && Array.isArray(curriculum.topics) ? curriculum : { levels: [], topics: [] };
    this.levels = this.curriculum.levels?.length ? this.curriculum.levels : LEVELS.map((id) => ({ id, title: id, en: '' }));
    this.topics = this.curriculum.topics;
    this._topicMeta = new Map(this.topics.map((t, i) => [t.id, { ...t, index: i }]));
    this.topicsByLevel = {};
    for (const l of LEVELS) this.topicsByLevel[l] = [];
    for (const t of this.topics) (this.topicsByLevel[t.level] || (this.topicsByLevel[t.level] = [])).push(t);
    this.units = {};
    for (const t of this.topics) {
      const k = `${t.level}/${t.unit || ''}`;
      (this.units[k] || (this.units[k] = [])).push(t);
    }
    this._topicCache = new Map(Object.entries(topics || {}));
    this._topicPending = new Map();

    // ---- vocab
    this.shards = [];
    this.words = [];
    const seen = new Map();
    for (const sh of vocab || []) {
      if (!sh || !Array.isArray(sh.words)) continue;
      this.shards.push({ shard: sh.shard, count: sh.words.length });
      for (const w of sh.words) {
        if (!w || typeof w.de !== 'string' || !w.pos) continue;
        const dupKey = `${w.de}|${w.pos}|${w.g || ''}`;
        if (seen.has(dupKey)) continue;
        seen.set(dupKey, true);
        this.words.push({ ...w, shard: sh.shard });
      }
    }
    // noun homonyms with different genders get a gender-qualified key: 'Band|noun.m'
    const deCount = new Map();
    for (const w of this.words) { const k = `${w.de}|${w.pos}`; deCount.set(k, (deCount.get(k) || 0) + 1); }
    this._wordByKey = new Map();
    for (const w of this.words) {
      const k = `${w.de}|${w.pos}`;
      w.key = deCount.get(k) > 1 && w.g ? `${k}.${w.g}` : k;
      this._wordByKey.set(w.key, w);
      if (!this._wordByKey.has(k)) this._wordByKey.set(k, w);
    }
    this.wordsByLevel = {}; this.wordsByTopic = {}; this.wordsByPos = {};
    for (const l of LEVELS) this.wordsByLevel[l] = [];
    for (const w of this.words) {
      (this.wordsByLevel[w.lvl] || (this.wordsByLevel[w.lvl] = [])).push(w);
      const tp = w.topic || 'Sonstiges';
      (this.wordsByTopic[tp] || (this.wordsByTopic[tp] = [])).push(w);
      (this.wordsByPos[w.pos] || (this.wordsByPos[w.pos] = [])).push(w);
    }
    this.wordTopics = Object.keys(this.wordsByTopic).sort((a, b) => a.localeCompare(b, 'de'));

    // ---- verbs
    this.verbs = (verbs && Array.isArray(verbs.verbs) ? verbs.verbs : []).filter((v) => v && v.inf);
    this.verbByInf = new Map(this.verbs.map((v) => [v.inf, v]));
  }

  topicMeta(id) { return this._topicMeta.get(id) || null; }
  /** Next topic in curriculum order (or null). */
  nextTopic(id) { const m = this._topicMeta.get(id); return m ? this.topics[m.index + 1] || null : null; }

  hasTopicLoaded(id) { return this._topicCache.has(id); }
  /** Lazily load a topic file. Resolves to the topic object, or null if missing/broken. */
  async getTopic(id) {
    if (this._topicCache.has(id)) return this._topicCache.get(id);
    if (!this._fetch || this.mode === 'data') return null;
    if (this._topicPending.has(id)) return this._topicPending.get(id);
    const p = getJSON(this._fetch, `${this.base}topics/${id}.json`)
      .then((t) => { this._topicCache.set(id, t); return t; })
      .catch((e) => { this.errors.push(String(e.message || e)); return null; })
      .finally(() => this._topicPending.delete(id));
    this._topicPending.set(id, p);
    return p;
  }
  /** Load all topics (e.g. for search/exam). Returns {id: topic|null}. */
  async loadAllTopics() {
    const out = {};
    await Promise.all(this.topics.map(async (t) => { out[t.id] = await this.getTopic(t.id); }));
    return out;
  }

  wordKey(w) { return w.key || `${w.de}|${w.pos}`; }
  wordByKey(key) { return this._wordByKey.get(key) || null; }
  word(de, pos) { return this._wordByKey.get(`${de}|${pos}`) || null; }
  verb(inf) { return this.verbByInf.get(inf) || null; }

  /** Words with level ≤ maxLevel; optional filters {pos, topic}. */
  wordsUpTo(maxLevel = 'B2', { pos, topic } = {}) {
    const li = levelIdx(maxLevel);
    const src = pos ? this.wordsByPos[pos] || [] : topic ? this.wordsByTopic[topic] || [] : this.words;
    return src.filter((w) => levelIdx(w.lvl) <= li && (!pos || w.pos === pos) && (!topic || w.topic === topic));
  }

  /** Simple search over de / en (accent- and case-insensitive). */
  searchWords(q, limit = 50) {
    const f = (s) => String(s || '').toLowerCase().replace(/ä/g, 'a').replace(/ö/g, 'o').replace(/ü/g, 'u').replace(/ß/g, 'ss');
    const n = f(q).trim();
    if (!n) return [];
    const starts = [], contains = [];
    for (const w of this.words) {
      const de = f(w.de), en = f(w.en);
      if (de.startsWith(n) || en.split(/,\s*/).some((x) => x.replace(/^to /, '').startsWith(n))) starts.push(w);
      else if (de.includes(n) || en.includes(n)) contains.push(w);
      if (starts.length >= limit) break;
    }
    return starts.concat(contains).slice(0, limit);
  }

  stats() {
    return { topics: this.topics.length, topicsLoaded: this._topicCache.size, words: this.words.length, verbs: this.verbs.length, shards: this.shards.length, mode: this.mode };
  }
}
